import { WordHuntLanguage } from "@/proto/minigames/v2/word_hunt_pb";

/** Every word the game accepts as a guess, per word length. */
export type AcceptedWords = ReadonlyMap<number, ReadonlySet<string>>;

const FILES: Readonly<Record<WordHuntLanguage, string | null>> = {
  [WordHuntLanguage.UNSPECIFIED]: null,
  [WordHuntLanguage.RUSSIAN]: "words/ru.txt",
  [WordHuntLanguage.ENGLISH]: "words/en.txt",
};

const loading = new Map<WordHuntLanguage, Promise<AcceptedWords>>();

/**
 * Reads a list generated by tools/word-lists/generate.py: `#` comments, `words <length>` section
 * lines, one lowercase word per line.
 */
export function parseWordList(text: string): AcceptedWords {
  const sections = new Map<number, Set<string>>();
  let current: Set<string> | null = null;
  for (const line of text.split("\n")) {
    if (line === "" || line.startsWith("#")) continue;
    const header = /^words (\d+)$/.exec(line);
    if (header) {
      current = new Set();
      sections.set(Number(header[1]), current);
    } else {
      current?.add(line);
    }
  }
  return sections;
}

/**
 * The language's word list, fetched once per session (and cached for offline play by the
 * service worker). The list only gates guesses in the UI: the game itself accepts any letters,
 * so a list that failed to load lets every guess through instead of blocking the game.
 */
export function acceptedWords(language: WordHuntLanguage): Promise<AcceptedWords> {
  const file = FILES[language];
  if (!file) return Promise.resolve(new Map());
  let pending = loading.get(language);
  if (!pending) {
    // The build number in the URL ties the cached list to the answers built into this app
    // version: a list cached before an update can never miss a newly added answer.
    pending = fetch(new URL(`${file}?build=${__APP_BUILD__}`, document.baseURI))
      .then((response) => {
        if (!response.ok) throw new Error(`${file}: HTTP ${response.status}`);
        return response.text();
      })
      .then(parseWordList)
      .catch((error: unknown) => {
        loading.delete(language);
        throw error;
      });
    loading.set(language, pending);
  }
  return pending;
}

/** Letters as the game spells them: lowercase, Russian `ё` as `е`. */
export function normalizeWord(word: string): string {
  return word.toLowerCase().replaceAll("ё", "е");
}
